def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return min(budget, DAILY_SALARY * 0.85)
        return min(budget, DAILY_SALARY * 0.2)

    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= DAILY_SALARY * 3:
            rich_opponents += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            urgent_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))

    highest_prev_bid = max(prev_bids) if prev_bids else 0
    avg_prev_bid = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    total_players = 1 + len(alive_opponents)
    expected_units = supply / float(WATER_REQ)
    scarcity = expected_units < total_players
    very_scarce = expected_units < max(1.0, total_players - 1)

    if hp <= 2 or no_water_days >= 2:
        base = DAILY_SALARY * 0.95
    elif hp <= 4 or no_water_days >= 1:
        base = DAILY_SALARY * 0.78
    else:
        if very_scarce:
            base = DAILY_SALARY * 0.68
        elif scarcity:
            base = DAILY_SALARY * 0.56
        else:
            base = DAILY_SALARY * 0.38

    if highest_prev_bid > 0:
        if hp <= 4 or no_water_days >= 1:
            target = max(base, highest_prev_bid + 2)
        else:
            if highest_prev_bid >= DAILY_SALARY * 0.9:
                target = DAILY_SALARY * 0.32
            else:
                target = max(base, avg_prev_bid + 1.5)
    else:
        target = base

    if urgent_opponents >= len(alive_opponents) // 2 + 1:
        target += 4
    if rich_opponents >= len(alive_opponents) // 2 + 1 and scarcity:
        target += 3

    if day >= 8:
        target += 4
    if day >= 9 and (hp <= 4 or no_water_days >= 1):
        target += 6

    if budget < DAILY_SALARY * 1.2:
        target = min(target, max(8, budget * 0.55))
    elif budget < DAILY_SALARY * 2:
        target = min(target, budget * 0.7)

    if hp >= 7 and no_water_days == 0 and not scarcity and highest_prev_bid >= DAILY_SALARY * 0.9:
        target = min(target, DAILY_SALARY * 0.25)

    if target < 0:
        target = 0
    return min(budget, target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    alive_opps = [o for o in opponents_status.values() if o.get('alive')]

    # Base urgency from our health and no-water streak
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # If we are in danger, bid aggressively; otherwise bid moderately.
    danger = 0
    if hp <= 2:
        danger += 2
    elif hp <= 4:
        danger += 1
    if no_water_days >= 1:
        danger += 1

    # Estimate how many full requirements the supply can cover.
    # Use int indices safely: only for list indexing; here just compute thresholds.
    # Normalize supply to [0,1]
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5

    # If we can afford to be competitive, bid around a fraction of salary.
    # Higher supply -> slightly lower bid; lower supply -> slightly higher bid.
    scarcity_factor = 1.0 + (0.5 - supply_norm) * 0.35

    # No trace exploitation possible: use yesterday bids if present, but keep it robust.
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
    else:
        highest_prev_bid = 0.0

    # Target bid logic
    if danger >= 2:
        target = DAILY_SALARY * 0.65 * scarcity_factor
    elif danger == 1:
        target = DAILY_SALARY * 0.55 * scarcity_factor
    else:
        target = DAILY_SALARY * 0.45 * scarcity_factor

    # If opponents previously bid high, slightly outbid to secure water.
    if highest_prev_bid > 0:
        # If they were already near our salary fraction, we need to match/beat.
        if highest_prev_bid >= DAILY_SALARY * 0.70:
            target = max(target, highest_prev_bid + 2.0)
        elif highest_prev_bid >= DAILY_SALARY * 0.45:
            target = max(target, highest_prev_bid + 1.0)

    # Ensure we don't bid more than we can pay.
    bid = min(budget, target)

    # Also ensure bid is not trivially low; minimum to have a chance.
    min_bid = max(DAILY_SALARY * 0.25, WATER_REQ * 1.5)
    bid = max(min_bid, bid)

    # Final clamp
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o.get('alive', True)]
    num_players = len(alive_opponents) + 1
    fair_share = DAILY_SALARY / num_players
    if my_status['hp'] < 3:
        return min(my_status['budget'], DAILY_SALARY * 0.8)
    return min(my_status['budget'], fair_share * 1.2)
